<?php require '../config.php'; if(!empty($_SESSION['admin_id'])){header('Location: dashboard.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=db()->prepare('SELECT * FROM admins WHERE email=? LIMIT 1');$q->execute([trim($_POST['email']??'')]);$a=$q->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location: dashboard.php');exit;}$err='Invalid email or password.';} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-login"><div class="login-card"><img src="../assets/images/school-logo.png" alt="Logo"><span class="eyebrow">ADMIN PORTAL</span><h1>Me’Raj School Admin</h1><?php if($err): ?><p class="error"><?=e($err)?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn" type="submit">Sign In</button></form><a href="../index.php">← Back to website</a></div></body></html>
